var a=`1261-macaroni-pie`;var t=`world-1261`;var n=`BB`;var o=`central-america-caribbean`;var r=8;var s=69;var l={en:`Macaroni Pie`,ua:`Макаронний пиріг`};var u={en:`Macaroni Pie is a dish from Barbados featuring macaroni, all-purpose flour, whole cow milk, cheddar cheese. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Макаронний пиріг, страва кухні країни Барбадос з такими основними складниками: макарони, пшеничне борошно універсальне, цільне коров'яче молоко, сир чедер. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the pasta in generously salted boiling water for about 12 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 12 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:12,i:[[`macaroni`,420,`g`],[`water`,1100,`ml`]]},{en:`Melt the fat, stir in flour and cook gently for about 9 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 9 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:9,i:[[`unsalted-butter`,65,`g`],[`all-purpose-flour`,55,`g`],[`whole-cow-milk`,640,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`cheddar-cheese`,340,`g`],[`dijon-mustard`,25,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:8,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 33 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 33 хвилин до готовності.`,t:[`baking`],m:33,i:[]}];var c={slug:a,id:t,country:`BB`,region:o,servings:8,minutes:69,title:l,text:u,steps:d};export{n as country,c as default,t as id,s as minutes,o as region,r as servings,a as slug,d as steps,u as text,l as title};